PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS edu_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,requested_school TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,verified_at TEXT NOT NULL,disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN(0,1)));
CREATE TABLE IF NOT EXISTS edu_schools(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'personal' CHECK(kind IN('personal','school')),owner_id TEXT NOT NULL REFERENCES edu_users(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('personal','pending','approved','suspended')),evidence_enabled INTEGER NOT NULL DEFAULT 0 CHECK(evidence_enabled IN(0,1)),agreement_reference TEXT NOT NULL DEFAULT '',approved_at TEXT,approved_by TEXT,retention_days INTEGER NOT NULL DEFAULT 90 CHECK(retention_days BETWEEN 7 AND 730),created_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS edu_personal_owner ON edu_schools(owner_id) WHERE kind='personal';
CREATE TABLE IF NOT EXISTS edu_memberships(school_id TEXT NOT NULL REFERENCES edu_schools(id),user_id TEXT NOT NULL REFERENCES edu_users(id),role TEXT NOT NULL DEFAULT 'teacher' CHECK(role IN('teacher','coordinator')),can_assess INTEGER NOT NULL DEFAULT 1 CHECK(can_assess IN(0,1)),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),PRIMARY KEY(school_id,user_id));
CREATE TABLE IF NOT EXISTS edu_sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES edu_users(id),school_id TEXT REFERENCES edu_schools(id),created_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS edu_session_expiry ON edu_sessions(expires_at);
CREATE TABLE IF NOT EXISTS edu_auth_tokens(hash TEXT PRIMARY KEY,browser_hash TEXT NOT NULL,email TEXT NOT NULL,name TEXT NOT NULL,school_name TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,mail_state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS edu_rate_limits(key TEXT PRIMARY KEY,period INTEGER NOT NULL,count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS edu_resources(id TEXT PRIMARY KEY,title TEXT NOT NULL,stage TEXT NOT NULL,term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 4),availability TEXT NOT NULL DEFAULT 'teacher' CHECK(availability IN('public','teacher','selected')),published_version INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','withdrawn')),updated_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,last_edit_token TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS edu_resource_versions(resource_id TEXT NOT NULL REFERENCES edu_resources(id),version INTEGER NOT NULL,payload TEXT NOT NULL,pdf_key TEXT,pdf_blob BLOB,pdf_size INTEGER NOT NULL DEFAULT 0,published_at TEXT,created_at TEXT NOT NULL,actor TEXT NOT NULL,review_note TEXT NOT NULL DEFAULT '',PRIMARY KEY(resource_id,version));
CREATE TABLE IF NOT EXISTS edu_resource_grants(resource_id TEXT NOT NULL REFERENCES edu_resources(id),school_id TEXT REFERENCES edu_schools(id),user_id TEXT REFERENCES edu_users(id),CHECK((school_id IS NULL) <> (user_id IS NULL)),UNIQUE(resource_id,school_id,user_id));
CREATE UNIQUE INDEX IF NOT EXISTS edu_school_grant ON edu_resource_grants(resource_id,school_id) WHERE school_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS edu_user_grant ON edu_resource_grants(resource_id,user_id) WHERE user_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS edu_favourites(user_id TEXT NOT NULL REFERENCES edu_users(id),resource_id TEXT NOT NULL REFERENCES edu_resources(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,resource_id));
CREATE TABLE IF NOT EXISTS edu_remarks(user_id TEXT NOT NULL REFERENCES edu_users(id),resource_id TEXT NOT NULL REFERENCES edu_resources(id),note TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,resource_id));
CREATE TABLE IF NOT EXISTS edu_groups(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES edu_schools(id),owner_id TEXT NOT NULL,name TEXT NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','closed')),created_at TEXT NOT NULL,closed_at TEXT,revision INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(school_id,owner_id) REFERENCES edu_memberships(school_id,user_id),UNIQUE(school_id,id));
CREATE TABLE IF NOT EXISTS edu_group_teachers(school_id TEXT NOT NULL,group_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(school_id,group_id,user_id),FOREIGN KEY(school_id,group_id) REFERENCES edu_groups(school_id,id),FOREIGN KEY(school_id,user_id) REFERENCES edu_memberships(school_id,user_id));
CREATE TABLE IF NOT EXISTS edu_assignments(id TEXT PRIMARY KEY,school_id TEXT NOT NULL,group_id TEXT NOT NULL,resource_id TEXT NOT NULL,version INTEGER NOT NULL,instructions TEXT NOT NULL DEFAULT '',selected_sections TEXT NOT NULL DEFAULT '[]',due_date TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(school_id,group_id) REFERENCES edu_groups(school_id,id),FOREIGN KEY(resource_id,version) REFERENCES edu_resource_versions(resource_id,version),UNIQUE(school_id,id),UNIQUE(school_id,group_id,id));
CREATE TABLE IF NOT EXISTS edu_learners(id TEXT PRIMARY KEY,school_id TEXT NOT NULL,group_id TEXT NOT NULL,alias TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(school_id,group_id) REFERENCES edu_groups(school_id,id),UNIQUE(school_id,group_id,alias),UNIQUE(school_id,id),UNIQUE(school_id,group_id,id));
CREATE TABLE IF NOT EXISTS edu_observations(id TEXT PRIMARY KEY,school_id TEXT NOT NULL,group_id TEXT NOT NULL,learner_id TEXT NOT NULL,assignment_id TEXT NOT NULL,criterion TEXT NOT NULL,level TEXT NOT NULL CHECK(level IN('not_observed','starting','developing','secure','extending')),evidence TEXT NOT NULL,feedback TEXT NOT NULL DEFAULT '',mode TEXT NOT NULL CHECK(mode IN('classroom','school_grounds','field','indoor','home')),observed_on TEXT NOT NULL,teacher_id TEXT NOT NULL,updated_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(school_id,group_id) REFERENCES edu_groups(school_id,id),FOREIGN KEY(school_id,group_id,learner_id) REFERENCES edu_learners(school_id,group_id,id),FOREIGN KEY(school_id,group_id,assignment_id) REFERENCES edu_assignments(school_id,group_id,id));
CREATE TABLE IF NOT EXISTS edu_reports(id TEXT PRIMARY KEY,school_id TEXT NOT NULL,group_id TEXT NOT NULL,learner_id TEXT,snapshot TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(school_id,group_id) REFERENCES edu_groups(school_id,id),FOREIGN KEY(school_id,group_id,learner_id) REFERENCES edu_learners(school_id,group_id,id));
CREATE TABLE IF NOT EXISTS edu_interests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES edu_users(id),school_id TEXT REFERENCES edu_schools(id),stage TEXT NOT NULL,mode TEXT NOT NULL,preferred_term TEXT NOT NULL,approximate_count INTEGER NOT NULL CHECK(approximate_count BETWEEN 1 AND 500),message TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new');
CREATE TABLE IF NOT EXISTS edu_audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,school_id TEXT,action TEXT NOT NULL,object_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS edu_groups_scope ON edu_groups(school_id,owner_id);
CREATE INDEX IF NOT EXISTS edu_observations_scope ON edu_observations(school_id,group_id,learner_id);
